import type { ArchitectureNode, EvidenceKind, PortfolioStatus, ProductEconomics, TechnologyStatus } from './portfolio';

type Metric = { label: string; target: string; kind: EvidenceKind; note: string };
type StackItem = { name: string; role: string; status: TechnologyStatus; reason: string; alternatives: string; evidence: string };
type ComponentDetail = Pick<ArchitectureNode, 'role' | 'technology' | 'reason' | 'alternatives' | 'inputs' | 'outputs' | 'dependencies' | 'failureModes' | 'cost' | 'status'>;
type Enhancement = {
  status: PortfolioStatus; flagship?: boolean; whyNow: string; buyer: string; market: string;
  metrics: Metric[]; alternatives: string[]; validation: string[]; functionalRequirements: string[];
  nonFunctionalRequirements: string[]; adoption: string[];
  decisions: Array<{ decision: string; rationale: string; rejected: string }>;
  economics: ProductEconomics; blueprint: string; sources: Array<{ label: string; url: string; note: string }>;
  stack: StackItem[]; components: Record<string, ComponentDetail>;
};

const c = (role: string, technology: string, reason: string, alternatives: string[], inputs: string[], outputs: string[], dependencies: string[], failureModes: string[] | string, cost?: string, status?: TechnologyStatus): ComponentDetail => {
  if (!status) return { role, technology, reason, alternatives, inputs, outputs, dependencies: ['Build artifact'], failureModes: dependencies, cost: String(failureModes), status: cost as TechnologyStatus };
  return { role, technology, reason, alternatives, inputs, outputs, dependencies, failureModes: Array.isArray(failureModes) ? failureModes : [failureModes], cost: cost ?? 'Cost model pending', status };
};
const metric = (label: string, target: string, kind: EvidenceKind, note: string): Metric => ({ label, target, kind, note });
const stack = (name: string, role: string, status: TechnologyStatus, reason: string, alternatives: string, evidence: string): StackItem => ({ name, role, status, reason, alternatives, evidence });
const economics = (formula: string, unit: string, assumptions: ProductEconomics['assumptions'], interpretation: string): ProductEconomics => ({ formula, unit, assumptions, interpretation });

